#!/usr/bin/env python3
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
BASE='/dc-public-realm'

home=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diplomatic Gifts in Washington</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.hero{{max-width:800px;margin:2rem 0}}.hero h1{{margin-bottom:.7rem}}.project{{border-left:4px solid #5a3d16;background:#fffdf8;padding:1rem 1.2rem;margin:2rem 0}}.project h2{{margin-top:.2rem}}.path{{font-family:ui-sans-serif,system-ui,sans-serif;color:#666}}.callout{{background:#f6f6f3;padding:1rem;margin:1.2rem 0}}.actions{{margin:1.2rem 0}}.actions .button{{margin-bottom:.5rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · research alpha</div><nav><a href="{BASE}/">Home</a><a href="{BASE}/objects/jose-gervasio-artigas/">Artigas</a><a href="{BASE}/collaborate/artigas/">Collaborate</a><a href="{BASE}/methodology/">Methodology</a></nav></header><main><section class="hero"><div class="kicker">PUBLIC ART · DIPLOMATIC HISTORY · SOURCE PROVENANCE</div><h1>Diplomatic Gifts in Washington</h1><p class="lede">A public research project tracing the histories of diplomatic monuments in Washington, D.C.—and tracing where the claims about those objects came from.</p><p>The project publishes historical evidence alongside uncertainty, conflicting records, and open research questions. Multiple institutional citations are not treated as independent confirmation until their source relationships are understood.</p></section><section class="project"><div class="kicker">CURRENT PROJECT · URUGUAY</div><h2>José Gervasio Artigas Memorial</h2><p>The Artigas memorial is the current test case for a claim-level approach to public art history. U.S., Uruguayan, National Park Service, and Smithsonian records do not align cleanly on the sculpture's predecessor, fabrication history, and creative roles.</p><p class="path">Narrative → citation → evidence → claim provenance → research task</p><div class="actions"><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">Explore the Artigas record</a><a class="button" href="{BASE}/collaborate/artigas/">Help trace the record</a><a class="button" href="{BASE}/review/artigas/">Scholarly review brief</a></div></section><section><h2>What the project is testing</h2><div class="grid"><article class="card"><h3>Object history</h3><p>Who commissioned, designed, modeled, cast, gifted, installed, and now cares for a monument?</p></article><article class="card"><h3>Knowledge history</h3><p>Did later catalogs independently establish a claim, or inherit it from the same earlier publication or archival record?</p></article><article class="card"><h3>Public collaboration</h3><p>Can unresolved scholarship be divided into small, useful tasks that archivists, historians, librarians, students, and interested readers can help solve?</p></article></div></section><section><h2>Why Artigas is useful</h2><p>The Smithsonian Art Inventories record cites several earlier research streams, while an official Uruguayan heritage record gives a more granular account of the earlier monument's creative history. The project preserves those differences rather than silently normalizing them.</p><div class="callout"><strong>Current research question:</strong> Can we reconstruct where the major claims about the Washington Artigas memorial actually originated?</div><p>Open work includes recovering Goode's 1974 Artigas pages, locating Michael Richman's 1967–69 research, identifying the exact NPS 1985 record, recovering the 1991 Smithsonian project files, and locating underlying Uruguayan and diplomatic records.</p><a class="button" href="{BASE}/collaborate/artigas/">Choose a collaboration task</a></section><section><h2>Other objects in the alpha</h2><div class="grid"><article class="card"><div class="kicker">ARGENTINA</div><h3><a href="{BASE}/objects/jose-de-san-martin/">José de San Martín</a></h3><p>A second test case for attribution conflicts and object lineage.</p></article><article class="card"><div class="kicker">CUBA</div><h3><a href="{BASE}/objects/cuban-american-friendship-urn/">Cuban-American Friendship Urn</a></h3><p>A harder diplomatic-history case involving fragmented records and changing political contexts.</p></article></div></section><section><h2>How claims are presented</h2><p>The Artigas prototype distinguishes <strong>Historical record</strong>, <strong>Attribution</strong>, and <strong>Interpretation</strong>. These describe the kind of scholarly proposition, not a confidence score. Evidence panels show supporting or contradictory records and, where possible, where a source got the claim.</p><p><a href="{BASE}/methodology/">Read the methodology</a> · <a href="https://github.com/danielastone/dc-public-realm">View the research repository</a></p></section></main><footer>Research leads do not affect claim status until the underlying material is examined and reviewed.</footer></body></html>'''

collab=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Help trace the Artigas memorial record</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.ask{{border-left:4px solid #7a3e00;background:#fffdf8;padding:1rem;margin:1rem 0}}.small{{font-family:ui-sans-serif,system-ui,sans-serif;color:#666;font-size:.9rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · collaboration</div><nav><a href="{BASE}/">Home</a><a href="{BASE}/objects/jose-gervasio-artigas/">Artigas record</a><a href="{BASE}/review/artigas/">Scholarly review</a></nav></header><main><div class="kicker">CURRENT COLLABORATION · OBJ-0001</div><h1>Help trace the Artigas memorial record</h1><p class="lede">The Washington Artigas memorial has an unusually useful provenance problem: later institutional records repeat a detailed history, but the public record does not show which earlier source supports each individual claim.</p><h2>The research question</h2><p><strong>Can we reconstruct where the major claims about the Washington Artigas memorial actually came from?</strong></p><p>We are especially interested in the basis for calling the Washington sculpture a recast, the identity of its predecessor, the early-1940s casting date, the Washington caster or foundry, and the relationship among Smithsonian, NPS, Goode, Richman, and earlier records.</p><h2>You can help without solving the whole problem</h2><p>A page scan, archival citation, finding-aid entry, catalog identifier, newspaper page, diplomatic-file reference, correction, or introduction can materially advance the research.</p><article class="ask"><h3>Goode (1974), pp. 443–444</h3><p>Find the Artigas entry and any citations or acknowledgments that reveal its upstream sources.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/19">Detailed task</a></article><article class="ask"><h3>Michael Richman, 1967–69</h3><p>Locate the collection, folder, finding aid, or research notes behind the work cited by Smithsonian.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/20">Detailed task</a></article><article class="ask"><h3>National Park Service, 1985</h3><p>Identify the exact NPS record cited by the Smithsonian inventory and any sources it relied on.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/21">Detailed task</a></article><article class="ask"><h3>Smithsonian research project, 1991</h3><p>Find documentation showing what researchers examined and which conclusions resulted from that work.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/22">Detailed task</a></article><article class="ask"><h3>Uruguay, 1894–1896</h3><p>Locate the underlying commission and contract records concerning Juan Luis Blanes, Juan Manuel Blanes, and Dante Costa.</p><p class="small">A catalog record, archival citation, image, or authoritative reproduction is useful even if you cannot retrieve the full file.</p></article><article class="ask"><h3>Uruguay–United States, approximately 1947–1951</h3><p>Locate diplomatic, fabrication, shipping, dedication, or installation records concerning the Washington bronze.</p></article><h2>Why source ancestry matters</h2><p>If several later publications ultimately repeat the same earlier statement, they are not independent confirmation of that statement. Recovering the source genealogy lets the project distinguish independent evidence from inherited catalog information.</p><h2>What happens to a contribution?</h2><p>New material is reviewed as evidence with its source and provenance. It does not automatically overwrite an existing claim or become verified because it comes from an institution. Conflicting evidence is retained, and unresolved questions remain unresolved until the evidence supports a stronger conclusion.</p><p><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">See the evidence model in use</a><a class="button" href="{BASE}/review/artigas/">Professional review brief</a></p></main><footer>A research lead has no evidentiary effect until the underlying record is retrieved and reviewed.</footer></body></html>'''

(SITE/'index.html').write_text(home,encoding='utf-8')
d=SITE/'collaborate'/'artigas'; d.mkdir(parents=True,exist_ok=True); (d/'index.html').write_text(collab,encoding='utf-8')
print('Updated project front door and Artigas collaboration page')
